  try {
    const result = await migrateFile(args[0], args[1],
      args.length === 3 ? { region: args[2] } : {});
    console.log(JSON.stringify(result, null, 2));
  } catch (error) {
    console.error(`Migration failed: ${error.message}`);
    process.exitCode = 1;
  }
}

